/** How the notice about an earlier version's folders is worded, by which of them the daemon says is left (`left`): one
 * folder, which the sentence names by the daemon's own word for it, the directory's name; both; or, for anything else,
 * the code's own sentence, which holds whichever is left. */
function leftoversVariant(params: Readonly<Record<string, string | undefined>>): string | undefined {
  if (params.left === "rules" || params.left === "plugins") return "one";
  return params.left === "both" ? "both" : undefined;
}

